import random
import string
import math

def rand_parens(size: int, valid: bool = True, par: str = '()', sep = ''):
    if valid:
        size += size % 2
        seq = []
        cnt = 0
        for i in range(size):
            if cnt == 0 or (cnt < size - i and random.randint(0, 1)):
                if cnt == 0:
                    seq.append([])
                seq[-1].append(par[0])
                cnt += 1
            else:
                seq[-1].append(par[1])
                cnt -= 1
        seq = [''.join(subseq) for subseq in seq]
        if sep is not None:
            seq = sep.join(seq)
    else:
        assert sep == ''
        seq = rand_parens(size = (size + 1) // 2 - 1, valid = True, par = par) + par[1] + par[0] + rand_parens(size = (size + 1) // 2 - 1, valid = True, par = par)
    return seq

def generate_input(size: int, lid: int, cid: int):
    if lid > 0 and cid == 0:
        m = (size + 1) // 2
        input_string = '(' * m + ')' * m
    else:
        input_string = rand_parens(size = size)
    input_string = ' ' * random.randint(0, 2) + ''.join([c + ' ' * random.randint(0, 2) for c in input_string])
    return input_string,


def make_input(seed, scale):
    random.seed(seed)
    lid = scale // 1000
    cid = scale % 1000
    result = generate_input(scale, lid, cid)
    return result if isinstance(result, tuple) else (result,)

